seo_schema:
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Where is Shalimar OneWorld?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Shalimar OneWorld is an integrated township at Village Baghamau, Gomti Nagar Extension, Lucknow, near Amar Shaheed Path. It is developed by the Shalimar Group; most phases are registered by Shalimar Lakecity Pvt Ltd."
      }
    },
    {
      "@type": "Question",
      "name": "Which Shalimar OneWorld projects are on sale now?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Shalimar's project sheet of August 2026 lists Pinnacle, Marbella, Twenty One, Valencia Towers 2, Valencia Tower, Valencia County East, Valencia County East Phase 2, Whispering Woods, Belvedere Suites and Shalimar Business District (offices)."
      }
    },
    {
      "@type": "Question",
      "name": "What unit sizes are available in Shalimar OneWorld?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "On Shalimar's August 2026 project sheet, apartments range from 1,530 sq ft super built-up area (Marbella 2 BHK + Study, 964.67 sq ft carpet) to 5,340 sq ft (Belvedere Suites 4 BHK + S). Villas in Valencia County East are 6,530 sq ft, and in Phase 2 7,790 sq ft."
      }
    },
    {
      "@type": "Question",
      "name": "How do I get the current price of a Shalimar OneWorld project?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Prices change with each sheet. Tap Invest on any project in this guide or message DSD Properties on WhatsApp for the current price, availability and the full cost sheet, which should list every charge, GST, stamp duty and registration."
      }
    },
    {
      "@type": "Question",
      "name": "Who is the developer of Shalimar OneWorld?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Shalimar OneWorld is a Shalimar Group township. Most phases are registered on UP RERA by Shalimar Lakecity Pvt Ltd (formerly ANS Developers Pvt Ltd); Twenty One is registered by Shalimar Corp Ltd. Your agreement should name the same company as your phase's RERA certificate."
      }
    },
    {
      "@type": "Question",
      "name": "Are Whispering Woods and Belvedere Suites delayed?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Both RERA registrations ran until 30 September 2026, and Shalimar's sheet also shows September 2026 possession. As of 19 October 2026 the official website still lists both as ongoing. Ask for an RERA extension letter or a completion/occupancy certificate before paying further."
      }
    },
    {
      "@type": "Question",
      "name": "What does \"+ S\" mean in the unit type?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The project sheet writes units like \"3 BHK + S\" — an additional room beyond the bedrooms. Its exact use and size are in the floor plan; ask the sales team to show it before booking."
      }
    }
  ]
}
